const ALLOWED=new Set(["https://tehiceesto.com","https://www.tehiceesto.com","https://tehiceesto.vercel.app","https://protectorrudo.github.io"]);
// A discounted pack is NOT a fake 25k pack order. It is an explicitly paid
// entitlement inside a verified, non-refunded gift+pack Mercado Pago order.
async function hasDiscountedPack(db:any,email:string):Promise<boolean>{
  const {data:orders,error:orderError}=await db.from("orders")
    .select("id,gift_id,amount_minor")
    .eq("buyer_email",email).eq("provider","mercadopago").eq("status","approved")
    .not("paid_at","is",null).eq("refunded_amount_minor",0)
    .order("created_at",{ascending:false}).limit(100);
  if(orderError)throw Error("pack_orders_unavailable");
  if(!orders?.length)return false;
  const byId=new Map(orders.map((o:any)=>[o.id,o]));
  const {data:extras,error:extraError}=await db.from("gift_upsells")
    .select("order_id,amount_minor,provider_order_id,checkout_url,paid_at")
    .in("order_id",orders.map((o:any)=>o.id))
    .eq("product_code","pack_juegos_v1").eq("status","approved")
    .not("paid_at","is",null).is("provider_order_id",null).is("checkout_url",null);
  if(extraError)throw Error("pack_entitlements_unavailable");
  if(!extras?.length)return false;
  const gifts=[...new Set(extras.map((e:any)=>byId.get(e.order_id)?.gift_id).filter(Boolean))];
  const {data:stories,error:giftError}=await db.from("gifts")
    .select("id,story_data").in("id",gifts);
  if(giftError)throw Error("pack_receipt_unavailable");
  const storyById=new Map((stories||[]).map((g:any)=>[g.id,g.story_data]));
  return extras.some((e:any)=>{
    const order=byId.get(e.order_id),story=storyById.get(order?.gift_id);
    const c=story&&typeof story==="object"&&typeof story.checkout==="object"?story.checkout:{};
    const base=Number(c.baseAmountMinor),total=Number(order?.amount_minor);
    return e.amount_minor===1000000&&c.addonCode==="pack_juegos_v1"&&
      Number(c.addonAmountMinor)===1000000&&Number(c.totalAmountMinor)===total&&
      base>0&&base+1000000===total;
  });
}


async function hasComplimentaryPack(db:any,email:string):Promise<boolean>{
  // Authenticate ownership via the same confirmed email as the purchase.
  const {data:orders,error:orderError}=await db.from("orders")
    .select("id,gift_id").eq("buyer_email",email)
    .order("created_at",{ascending:false}).limit(100);
  if(orderError)throw Error("complimentary_orders_failed");
  if(!orders?.length)return false;
  const byOrder=new Map(orders.map((o:any)=>[o.id,o.gift_id]));
  const {data:grants,error}=await db.from("complimentary_access_grants")
    .select("order_id,gift_id,expires_at")
    .in("order_id",orders.map((o:any)=>o.id))
    .eq("product_code","pack_juegos_v1").is("revoked_at",null);
  if(error)throw Error("complimentary_pack_lookup_failed");
  const valid=(grants||[]).filter((g:any)=>
    byOrder.get(g.order_id)===g.gift_id&&
    (!g.expires_at||Date.parse(g.expires_at)>Date.now()));
  if(!valid.length)return false;
  // Original checkout must really contain the purchased 4-game addon.
  const {data:extras,error:extraError}=await db.from("gift_upsells")
    .select("order_id,gift_id,product_code").in("order_id",valid.map((g:any)=>g.order_id))
    .eq("product_code","pack_juegos_v1");
  if(extraError)throw Error("complimentary_pack_source_failed");
  return valid.some((g:any)=>(extras||[]).some((e:any)=>
    e.order_id===g.order_id&&e.gift_id===g.gift_id));
}

